# Hypothesis: a decorator typed as Callable[Concatenate[int, P], R] -> Callable[P, R]
# drops the leading int from the signature, so callers must omit it and an extra
# positional argument is rejected.
from typing import Callable, Concatenate, ParamSpec, TypeVar, reveal_type, assert_type

P = ParamSpec('P')
R = TypeVar('R')


def inject_ctx(fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(7, *args, **kwargs)

    return wrapper


@inject_ctx
def greet(ctx: int, name: str, *, excl: bool = False) -> str:
    return str(ctx) + ':' + name + ('!' if excl else '')


@inject_ctx
def total(ctx: int, *nums: int) -> int:
    return ctx + sum(nums)


reveal_type(greet)
reveal_type(total)
assert_type(greet('ann'), str)
assert_type(total(1, 2, 3), int)
assert greet('ann') == '7:ann'
assert greet('bob', excl=True) == '7:bob!'
assert total(1, 2, 3) == 13


def bad_call() -> str:
    try:
        return greet(1, 'x', 'y')  # expect-error
    except TypeError:
        return 'rejected'


assert bad_call() == 'rejected'
